"""Explain semaphore permits, initialization, ownership and down paths."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1521': ('교실에 빌릴 수 있는 가위가 세 개 있다고 해 봅시다. 세 명이 하나씩 빌리면 남은 수는 0이고 다음 친구는 기다려야 합니다. 가위를 기다리는 사람 수와 남은 가위 수는 서로 다릅니다.', '세마포어의 남은 허가 수와 대기 명단, 잠금의 역할을 구별합니다.', 'count=3에서 A 획득 → 2, B 획득 → 1, C 획득 → 0을 적으세요. D는 count를 음수로 만드는 대신 대기 명단에 들어간다고 그리세요.', ['세마포어(semaphore)는 동시에 허용할 사용 수를 관리하는 도구입니다. 여기서 허가는 가위 한 개를 빌릴 수 있는 표와 비슷합니다. 프로그램은 허가를 얻은 뒤 자원을 사용하고 정해진 때에 돌려줍니다.', 'struct semaphore에는 lock, count, wait_list라는 세 정보 칸이 있습니다. struct는 관련된 정보를 묶는 C 자료 형식입니다. count는 지금 추가로 얻을 수 있는 허가 수이며 unsigned int, 즉 음수 없는 정수로 저장됩니다.', 'wait_list는 허가가 없어 기다리는 작업들을 잇는 목록입니다. 남은 허가가 0일 때 아무도 기다리지 않을 수도 있고 여러 작업이 기다릴 수도 있습니다. count=0만 보고 대기자가 정확히 몇 명인지 알 수 없는 이유입니다.', 'lock의 형식은 raw_spinlock_t입니다. 잠금은 여러 CPU가 count와 목록을 동시에 잘못 바꾸지 않도록 짧은 구간을 보호합니다. 예를 들어 마지막 허가 1을 두 작업이 함께 읽고 각자 가져갔다고 생각하는 일을 막아야 합니다.', '허가가 있으면 down 계열은 잠금을 잡은 상태에서 하나 줄이는 빠른 경로로 갑니다. 허가가 없으면 종류에 따라 대기하거나 실패하는 규칙을 따릅니다. 실제로 잠들어 기다리는 느린 경로에서는 잠금을 풀고, 돌아온 뒤 다시 잡습니다. 기다리는 내내 raw 잠금을 쥐는 것이 아닙니다.', '세마포어는 실제 가위나 파일을 담지 않습니다. 허가와 대기자를 관리하므로 실제 자원 사용 규칙은 호출자가 지켜야 합니다. 구조체 멤버를 직접 바꾸기보다 down·up 같은 정해진 API를 사용하고, 성공한 획득과 반환을 올바르게 대응시켜야 합니다.'], [('count=2라는 값은 무엇을 뜻하나요?', ['지금 잠든 작업이 반드시 두 개라는 뜻이에요', '추가로 얻을 수 있는 허가가 두 개라는 뜻이에요'], 'count는 남은 허가 수입니다. 기다리는 작업은 wait_list에 따로 연결되므로 count를 대기자 수로 읽으면 안 돼요. 가위가 두 개 남았다는 말과 기다리는 친구가 두 명이라는 말은 다릅니다.'), ('허가가 없어 실제로 잠들어 기다릴 때 raw 잠금을 계속 잡나요?', ['아니요. 풀고 기다린 뒤 다시 잡아요', '네. 허가를 받을 때까지 잠금을 놓지 않아요'], '잠금은 count와 목록을 바꾸는 구간을 보호합니다. 느린 대기 경로는 unlock → schedule_timeout → lock 순서예요. 다른 작업이 허가를 반환할 수 있도록 실제 기다림 동안에는 풀어야 합니다.')]), 'os1522': ('빌릴 가위가 세 개라면 처음 표에 3이라고 적어야 합니다. 실수로 -1이라고 썼다고 초기화 함수가 “잘못 썼네” 하고 자동으로 0으로 고쳐 주는 것은 아닙니다.', '초기화 입력의 책임과 빈 대기 목록을 만드는 동작을 이해합니다.', 'sema_init(sem, 3)을 생각하며 lock 준비, count=3, 빈 wait_list를 그리세요. 이미 기다리는 A가 있을 때 다시 초기화하는 상황에는 주의 표시를 하세요.', ['sema_init은 세마포어를 처음 사용할 상태로 만듭니다. 인자 sem은 준비할 자료의 주소이고 val은 처음 허가 수입니다. val의 형식은 int이지만 저장될 count는 unsigned int입니다. 입력과 저장 칸의 자료형을 모두 살펴야 합니다.', '본문은 초기화 규칙으로 만든 구조체 전체를 *sem에 대입합니다. 별표는 이 식에서 주소가 가리키는 실제 자료를 뜻합니다. 잠금을 초기 상태로 만들고 count에 val을 넣으며 wait_list의 앞뒤 연결을 자기 자신으로 만듭니다.', '자기 자신을 가리키는 연결은 원형 목록에서 빈 줄을 뜻합니다. 아직 기다리는 항목이 없다는 시작 상태입니다. 전체를 초기화하므로 기존 대기 항목들을 찾아 옮기거나 보존하는 동작은 하지 않습니다.', '음수 입력을 검사해 0으로 고치는 if문은 없습니다. 예를 들어 -1을 음수 없는 unsigned int에 넣으면 그 형식의 큰 양수 값으로 변환됩니다. 그것을 자원 수로 쓰면 전혀 다른 뜻이 됩니다. 따라서 사용자가 유효한 음수가 아닌 초기 허가 수를 정해야 합니다.', '이후 lockdep_init_map으로 잠금 검사에 사용할 분류와 이름을 연결합니다. lockdep는 잠금 사용 문제를 찾는 데 도움을 주는 기능입니다. 이것이 잘못된 허가 수를 고치거나 대기자를 자동으로 복구해 주지는 않습니다.', 'DEFINE_SEMAPHORE(name, n)는 선언하면서 이름과 초기 허가 수를 정하는 매크로입니다. 실행 중 sema_init을 쓰든 선언 시 준비하든 사용 전에 초기화해야 합니다. 이미 사용 중인 줄을 다시 빈 상태로 덮으면 기다리는 작업의 연결을 잃을 수 있으므로 초기화를 반환이나 취소 대신 쓰지 마세요.'], [('sema_init에 음수를 주면 자동으로 0으로 제한해 주나요?', ['네. 모든 잘못된 숫자를 알아서 고쳐요', '아니요. 검사 없이 초기 count에 대입해요'], '본문에 음수 검사나 범위를 제한하는 분기가 없습니다. int 입력은 unsigned int 저장 과정에서 변환될 수 있으므로 호출자가 올바른 값을 줘야 해요. 초기화 함수 이름이 입력 검증까지 뜻하지는 않습니다.'), ('사용 중인 세마포어를 다시 초기화하면 기존 대기 줄이 보존되나요?', ['아니요. 새 빈 목록 상태로 덮으므로 연결을 잃을 수 있어요', '네. 모든 대기자를 새 목록에 자동으로 옮겨요'], '초기화는 구조체 전체를 시작 상태로 대입합니다. 기존 목록을 순회해 옮기는 코드가 없어요. 이미 사용하는 자료의 상태 변경과 최초 초기화를 구별해야 합니다.')]), 'os1523': ('가위 대여 담당자가 빌려 준 표를 다른 담당자에게 받아도 되는 규칙을 생각해 봅시다. “누가 빌렸는지 검사하는 열쇠”와 “사용 허가 수를 관리하는 표”는 같은 도구가 아닙니다.', '허가 수가 1이어도 세마포어와 mutex의 소유자 규칙이 다른 이유를 이해합니다.', 'A가 down으로 허가 획득 → 정해진 규칙에 따라 B가 up으로 반환을 그리세요. 아무 때나 여러 번 반환해도 된다는 뜻은 아니라고 덧붙이세요.', ['초기 허가 수를 1로 둔 세마포어는 한 번에 하나의 허가를 사용하는 방식으로 쓸 수 있습니다. 이를 binary semaphore라고 부릅니다. binary는 여기서 한 개의 허가로 제한해서 쓰는 방식을 가리킵니다.', '하지만 count를 1로 시작했다고 mutex와 같은 자료구조가 되지는 않습니다. 이 세마포어에는 잠금 소유 task를 기록하는 owner 칸이 없습니다. 일반 mutex의 같은 소유자가 잠금을 풀어야 한다는 규칙과 다릅니다.', '원문은 down을 호출한 작업과 다른 작업이 up을 호출할 수 있다고 설명합니다. 예를 들어 A가 획득한 뒤, 약속된 처리 흐름에서 B가 허가를 돌려주는 사용이 가능합니다. 실제 사용 규칙과 자료 수명을 갖춘 상황이어야 합니다.', '소유자 제한이 없다는 말은 아무 때나 up을 반복해도 좋다는 뜻이 아닙니다. 초기값 1도 반환을 잘못 여러 번 하면 의도한 허가 제한이 깨질 수 있습니다. 세마포어가 최초 값 1을 자동으로 최대 한도로 기억해 모든 추가 반환을 막는다고 가정하지 마세요.', '헤더는 up과 down_trylock을 인터럽트 문맥에서도 사용할 수 있다고 명시합니다. 이 계약을 허가가 없어 잠들 수 있는 일반 down으로 확대하면 안 됩니다. 각 API가 실제로 기다리는지, 잠들지 않고 결과를 돌려주는지 확인해야 합니다.', '따라서 반환할 주체와 자원을 다 쓰는 시점을 정해야 합니다. 소유자 검사나 소유자에 기반한 우선순위 상속을 이 세마포어가 자동 제공한다고 기대하지 마세요. 하나만 사용하게 한다는 숫자 규칙과 누가 소유하고 풀어야 하는지는 서로 다른 약속입니다.'], [('up은 반드시 이전 down을 수행한 바로 그 작업만 호출해야 하나요?', ['네. 항상 mutex와 같은 소유자 검사예요', '아니요. 정해진 사용 규칙에 따라 다른 작업도 호출할 수 있어요'], '원문은 세마포어에 소유자 규칙이 없어서 다른 작업의 up을 허용합니다. 다만 누가 언제 허가를 반환할지는 호출자가 정해야 해요. 소유자가 없다고 잘못된 추가 반환도 안전한 것은 아닙니다.'), ('허가 수를 1로 시작하면 mutex의 모든 사용 규칙도 같아질까요?', ['아니요. 소유자와 반환 주체 등의 약속이 달라요', '네. 같은 숫자면 자료구조와 검사도 모두 같아요'], '초기 허가 하나는 동시에 사용할 수 있는 수를 정할 뿐입니다. owner 정보나 mutex의 해제 규칙을 만들어 주지 않아요. 구조체와 API 계약을 따로 확인해야 합니다.')]), 'os1524': ('가위가 남아 있으면 하나를 빌리고 바로 가면 됩니다. 모두 빌려 갔다면 누군가 돌려줄 때까지 기다려야 합니다. 같은 입구라도 남은 수에 따라 실제로 하는 일이 달라집니다.', 'down의 즉시 획득과 대기 경로, 잠들 수 있는 상황의 조건을 이해합니다.', 'count=2이면 잠금 잡기 → 1로 줄이기 → 잠금 풀기를 그리세요. count=0이면 __down 대기로 갈라지는 화살표를 추가하세요.', ['down은 세마포어 허가 하나를 얻는 함수입니다. 먼저 might_sleep로 잠들 수 있는 코드 경로임을 알리고 부적절한 실행 상황을 검사하는 데 도움을 줍니다. 항상 실제로 잠들게 하는 명령은 아닙니다.', '다음 raw_spin_lock_irqsave로 count와 대기 줄을 보호합니다. 이 호출은 현재 CPU의 인터럽트 상태를 저장하고 인터럽트를 끄며 잠금을 잡습니다. 두 작업이 마지막 허가 하나를 동시에 가져갔다고 판단하지 않게 해야 합니다.', '잠금 안에서 count > 0이면 count--를 합니다. 예를 들어 2라면 1로 줄입니다. 이 빠른 길에서는 대기 항목을 등록하지 않습니다. likely는 이 분기가 흔할 것으로 예상한다는 코드 힌트이지 허가 수를 바꾸는 명령이 아닙니다.', 'count=0이면 __down을 부릅니다. 이 내부 함수는 TASK_UNINTERRUPTIBLE과 MAX_SCHEDULE_TIMEOUT을 공통 대기에 전달합니다. 유한한 시간 제한이나 일반 신호 중단을 선택한 변형이 아닙니다. 실제 기다림 전에는 raw 잠금을 풀고 돌아오면 다시 잡습니다.', '끝에는 raw_spin_unlock_irqrestore로 잠금을 풀고 이전 인터럽트 상태를 복구합니다. 하지만 irqsave가 있다고 잠들 수 없는 임의의 인터럽트 상황에서 대기해도 되는 것은 아닙니다. 자료 보호 방식과 잠들 수 있는 실행 상황은 다른 조건입니다.', '이 버전 원문은 일반 down 사용을 deprecated, 즉 새 사용을 권하지 않는 방식으로 설명하고 down_interruptible 또는 down_killable을 안내합니다. 반드시 즉시 성공함을 아는 일부 내부 사용의 주석을 일반적인 인터럽트 대기 허가로 읽지 마세요. 호출 목적에 맞는 중단 규칙과 잠들 수 있는 문맥을 확인해야 합니다.'], [('down이 잠금을 잡고 count=2를 확인했어요. 빠른 경로에서 무엇을 하나요?', ['언제나 먼저 대기 카드를 등록해요', 'count를 하나 줄여 1로 만들어요'], 'count > 0이면 sem->count--를 수행합니다. 허가가 이미 있으므로 느린 대기 경로를 호출하지 않아요. 대기 항목 등록은 허가가 없는 경로와 구별하세요.'), ('down에 irqsave 잠금이 있으니 아무 인터럽트 문맥에서나 잠들어도 될까요?', ['아니요. 실제 잠들 수 있는 상황인지 따로 지켜야 해요', '네. raw 잠금이 모든 수면을 허용해요'], 'irqsave는 공유 자료와 인터럽트 상태를 보호하는 방식입니다. 실행을 멈추고 기다려도 되는 문맥으로 바꾸어 주지 않아요. 즉시 성공이 보장된 특수 사용과 일반적인 수면 경로를 섞으면 안 됩니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_376.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
